е, місце народження і сімейний стан.", "points": [{"ua": "ім’я й прізвище", "keys": [["prezime"], ["ime="], ["zovem se"]]}, {"ua": "місце народження", "keys": [["mjesto rođenj"], ["rođen"]]}, {"ua": "сімейний стан", "keys": [["bračno stanj"], ["udan"], ["oženjen"], ["razveden"], ["neudan"], ["neoženjen"]]}], "hints": ["ime i prezime", "mjesto rođenja", "bračno stanje", "tiskanim slovima"], "models": ["Ime i prezime: Olena Kovalenko. Mjesto rođenja: Kijev. Bračno stanje: udana.", "Zovem se Taras Bondar, rođen sam u Lavovu, oženjen sam."]}}, {"id": "c760bb38-2274-5f09-84a9-3cdffd787e58", "lesson": "b095637e-0644-507e-8f3d-d323483dd3e4", "type": "mediation", "level": "A0", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "Заповнити друкованими літерами, підписати і обов’язково додати копію паспорта.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "friend_ua": "Що треба зробити з анкетою?", "direction": "hr_ua", "points": [{"ua": "друкованими літерами", "keys": [["друкован"]]}, {"ua": "підписати", "keys": [["підпис"]]}, {"ua": "копія паспорта", "keys": [["копі", "паспорт"]]}], "hints": [], "models": ["Заповнити друкованими літерами, підписати і обов’язково додати копію паспорта."], "source_hr": "Obrazac ispunite tiskanim slovima i potpišite. Obvezno priložite kopiju putovnice."}}, {"id": "bbc9a7a1-b372-513d-9c0a-234297fb40e8", "lesson": "19df3241-90f3-5450-94ac-642d79fb2869", "type": "write_message", "level": "A0", "skill": "writing", "question": "Напишіть у MUP: ви хочете подати заяву на тимчасове перебування, спитайте, які документи потрібні.", "answer": "Poštovani, želim predati zahtjev za privremeni boravak. Koji dokumenti su potrebni?", "task": {"situation_ua": "Напишіть у MUP: ви хочете подати заяву на тимчасове перебування, спитайте, які документи потрібні.", "points": [{"ua": "подати заяву", "keys": [["zahtjev"]]}, {"ua": "тимчасове перебування", "keys": [["privremen", "boravak"]]}, {"ua": "які документи", "keys": [["dokument"]]}], "hints": ["predati zahtjev", "privremeni boravak", "koji dokumenti", "potrebni su"], "models": ["Poštovani, želim predati zahtjev za privremeni boravak. Koji dokumenti su potrebni?"]}}, {"id": "ededdef2-c9cc-52f9-95ce-d8e169bfaff5", "lesson": "19df3241-90f3-5450-94ac-642d79fb2869", "type": "mediation", "level": "A0", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "Рішення можна забрати особисто у віконці 4, з понеділка до п’ятниці, з 8 до 12.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "friend_ua": "Коли й де забрати рішення?", "direction": "hr_ua", "points": [{"ua": "віконце 4", "keys": [["4"]]}, {"ua": "з понеділка до п’ятниці", "keys": [["понеділ", "п''ятниц"]]}, {"ua": "з 8 до 12", "keys": [["8", "12"]]}], "hints": [], "models": ["Рішення можна забрати особисто у віконці 4, з понеділка до п’ятниці, з 8 до 12."], "source_hr": "Rješenje možete preuzeti osobno na šalteru 4, od ponedjeljka do petka, 8–12 h."}}]'::jsonb)
      as t(id uuid, lesson uuid, type text, level text, skill text, question text, answer text, task jsonb)
  loop
    insert into public.exercises (id, exercise_type, question_text, correct_answer, options, level, order_index, status, task)
