  -- Самоперевірка: у кожному уроці партії — рівно по одній вправі кожного типу з коректним завданням
  if exists (
    select 1 from unnest(array['78f28f85-dd8b-5e81-8a52-1b2dbce4eb34'::uuid, '1436c20e-0aea-550a-b66d-fb3149a1c2e2'::uuid, '32f5d97b-d6c0-57af-9e48-86f9ee9a932d'::uuid, '0ecb6f19-2630-533d-9f1b-85102442af08'::uuid, 'e8f4a2ca-af87-5d99-9f9e-a24cfadf73c9'::uuid, 'f51692d8-cb95-5f2e-8263-f3728f5e10c0'::uuid, '7bbaf7ff-10bb-512a-91c5-798b59ec92a5'::uuid, 'c9e045fb-91ff-52a2-9916-1b698d30eb19'::uuid, '8b30911e-4e57-5648-9ff6-bd11c1b0e27e'::uuid, '77d640c4-4190-544a-8094-4e699f9a0a10'::uuid, 'e6925fe5-e7fb-5594-9d3f-87fab1b5598d'::uuid, 'e495a4dd-a963-5a5f-af8c-09b2ea6a2ea0'::uuid, '0e925295-2766-5931-b031-2412682bc6f8'::uuid, '28913ad6-490f-5d89-bad7-9b303c673fcd'::uuid, 'b01e2f67-3e7a-5ab6-99bb-fae374f431e0'::uuid, '288e7610-99c8-5696-989a-86f60ce38b0a'::uuid, '6836e57c-030c-59f8-9818-b44c08b126a6'::uuid, '0addd5be-230b-582f-baed-a5d18eb1d619'::uuid, '55af257e-e4d1-51ed-9637-388a7e0b4baf'::uuid, '1e0384e5-6097-56ed-ab56-cf530f02ab73'::uuid, 'e5b81eb1-8ea8-5ff4-a987-e5e46421302b'::uuid, 'e0b9d742-0418-597b-9482-b6e2d82469da'::uuid, 'edbae9ca-c4f4-575d-b876-d50b0a1fd9b5'::uuid, '599fba4f-4cee-5a88-9f9b-5ce32a445554'::uuid, 'fbc71f82-e715-5bab-a990-b8542fb0fe01'::uuid, '48f26e9d-96c5-5189-8ec6-db1f9d58e200'::uuid, 'd2689a70-cb73-515f-9d81-6bb0f0fc1cff'::uuid, 'b095637e-0644-507e-8f3d-d323483dd3e4'::uuid, '19df3241-90f3-5450-94ac-642d79fb2869'::uuid]) as l(id), unnest(array['write_message', 'mediation']) as k(t)
    where (select count(*) from public.lesson_items li join public.exercises e on e.id = li.item_id
           where li.lesson_id = l.id and li.item_type = 'exercise' and e.exercise_type = k.t and e.status = 'PUBLISHED'
             and not li.required and jsonb_array_length(e.task -> 'points') between 1 and 5) <> 1) then
    raise exception 'Не в кожному уроці партії рівно одна вправа кожного типу';
  end if;
  raise notice 'Готово: письмо й переказ (модулі A0.6–A0.10) — вправ створено %, додано в уроки % (усього в партії 58)', v_ex, v_items;
end
